extends Sprite2D

var gem_type = "ruby"
var fall_speed = 120.0
var score_value = 25


func _ready():
	modulate = Color.RED


func _process(delta):
	position.y += fall_speed * delta
	if position.y > 600.0:
		position.y = 50.0
		position.x = 300.0
		modulate = Color.RED


func check_limits():
	if position.y > 600.0:
		return true
	return false
